CREATE TABLE IF NOT EXISTS tenants (id BIGSERIAL PRIMARY KEY, tenant_id VARCHAR(100) UNIQUE NOT NULL, name VARCHAR(255) NOT NULL, tier VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, tenant_id VARCHAR(100) NOT NULL, username VARCHAR(255) NOT NULL, role VARCHAR(50) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS policies (id BIGSERIAL PRIMARY KEY, tenant_id VARCHAR(100) NOT NULL, policy_id VARCHAR(100) NOT NULL, data JSONB, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS claims (id BIGSERIAL PRIMARY KEY, tenant_id VARCHAR(100) NOT NULL, claim_id VARCHAR(100) NOT NULL, policy_id VARCHAR(100) NOT NULL, status VARCHAR(50), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customers (id BIGSERIAL PRIMARY KEY, tenant_id VARCHAR(100) NOT NULL, customer_id VARCHAR(100) NOT NULL, data JSONB, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS documents (id BIGSERIAL PRIMARY KEY, tenant_id VARCHAR(100) NOT NULL, document_id VARCHAR(100) NOT NULL, claim_id VARCHAR(100), metadata JSONB, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY, tenant_id VARCHAR(100) NOT NULL, event_type VARCHAR(100), payload JSONB, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_tenant_id_policies ON policies(tenant_id);
CREATE INDEX IF NOT EXISTS idx_tenant_id_claims ON claims(tenant_id);
CREATE INDEX IF NOT EXISTS idx_tenant_id_customers ON customers(tenant_id);
CREATE INDEX IF NOT EXISTS idx_tenant_id_documents ON documents(tenant_id);
CREATE INDEX IF NOT EXISTS idx_tenant_id_audit_logs ON audit_logs(tenant_id);
CREATE INDEX IF NOT EXISTS idx_policy_id_claims ON claims(policy_id);
CREATE INDEX IF NOT EXISTS idx_claim_id_documents ON documents(claim_id);
